"""Deterministic post-emitter stage for real, demand-created TypedDict contracts."""

from __future__ import annotations

import ast
from pathlib import Path
import textwrap

BEGIN = "# BEGIN CANONICAL EMITTER CONTRACT\n"
END = "# END CANONICAL EMITTER CONTRACT\n"
HEADER = (
    "# Copyright (c) Microsoft Corporation.\n"
    "# Licensed under the MIT license.\n"
    "# Generated by _scripts/lazy_model_emitter.py; do not edit by hand.\n"
)
MODEL_EXCLUDES = {
    "Any",
    "ItemOutputMessage",
    "Literal",
    "Optional",
    "OutputItemOutputMessage",
    "OutputMessageContent",
    "OutputMessageContentOutputTextContent",
    "OutputMessageContentRefusalContent",
    "Required",
    "TYPE_CHECKING",
    "TypedDict",
    "Union",
    "builtins",
}


def canonical(text: str) -> str:
    if BEGIN not in text:
        return text.rstrip() + "\n"
    block = text.split(BEGIN, 1)[1].split(END, 1)[0]
    if not block.startswith("if TYPE_CHECKING:\n"):
        raise ValueError("Invalid canonical model contract marker")
    return textwrap.dedent(block[len("if TYPE_CHECKING:\n") :]).rstrip() + "\n"


def definitions(tree: ast.Module) -> dict[str, ast.ClassDef | ast.Assign]:
    result = {}
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            result[node.name] = node
        elif isinstance(node, ast.Assign):
            if len(node.targets) != 1 or not isinstance(node.targets[0], ast.Name):
                raise ValueError("Unsupported generated assignment")
            result[node.targets[0].id] = node
        elif not isinstance(node, (ast.Import, ast.ImportFrom, ast.If, ast.Expr)):
            raise ValueError(f"Unsupported generated model statement: {type(node).__name__}")
    return result


def imported_names(tree: ast.Module) -> list[str]:
    names = []
    for node in tree.body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            names.extend(alias.asname or alias.name for alias in node.names if not alias.name.startswith("_"))
    return names


class ReferenceRewriter(ast.NodeTransformer):
    def __init__(self, names: set[str], forward: bool = False) -> None:
        self.names = names
        self.forward = forward

    def visit_Name(self, node: ast.Name) -> ast.AST:
        if isinstance(node.ctx, ast.Load) and node.id in self.names:
            if self.forward:
                return ast.copy_location(
                    ast.Attribute(value=ast.Name(id="_types", ctx=ast.Load()), attr=node.id, ctx=ast.Load()), node
                )
            return ast.copy_location(
                ast.Call(func=ast.Name(id="_resolve", ctx=ast.Load()), args=[ast.Constant(node.id)], keywords=[]), node
            )
        return node

    def visit_Subscript(self, node: ast.Subscript) -> ast.AST:
        # Strings inside Literal are values, not forward references.
        if isinstance(node.value, ast.Name) and node.value.id == "Literal":
            return node
        return self.generic_visit(node)

    def visit_Constant(self, node: ast.Constant) -> ast.AST:
        if isinstance(node.value, str) and not self.forward:
            expression = ast.parse(node.value, mode="eval")
            rewritten = ReferenceRewriter(self.names, forward=True).visit(expression)
            return ast.copy_location(ast.Constant(ast.unparse(rewritten)), node)
        return node


def render_module(source: str, module: str, type_names: set[str]) -> tuple[str, list[str], list[str]]:
    tree = ast.parse(source)
    declarations = definitions(tree)
    exports = list(dict.fromkeys(imported_names(tree) + list(declarations)))
    public_models = []
    factories = []
    for name, declaration in declarations.items():
        if isinstance(declaration, ast.ClassDef):
            if any(not isinstance(base, ast.Name) or base.id != "TypedDict" for base in declaration.bases):
                raise ValueError(f"Unsupported generated model base: {name}")
            if any(not isinstance(item, (ast.AnnAssign, ast.Expr, ast.Pass)) for item in declaration.body):
                raise ValueError(f"Unsupported generated model body: {name}")
            public_models.append(name)
            # Reparse to leave the canonical input intact.
            node = ast.parse(ast.unparse(declaration)).body[0]
            for statement in node.body:
                if isinstance(statement, ast.AnnAssign):
                    statement.annotation = ReferenceRewriter(type_names).visit(statement.annotation)
            body = ast.unparse(ast.fix_missing_locations(node))
            body += (
                f"\n{name}.__qualname__ = {name!r}\n"
                f"if _version_info < (3, 13):\n    {name}.__doc__ = {ast.get_docstring(declaration, clean=False)!r}\n"
                f"return {name}\n"
            )
        else:
            value = ast.parse(ast.unparse(declaration.value), mode="eval").body
            if (
                isinstance(value, ast.Subscript)
                and isinstance(value.value, ast.Name)
                and value.value.id in ("Union", "Literal")
            ):
                public_models.append(name)
            value = ReferenceRewriter(type_names).visit(value)
            body = "return " + ast.unparse(ast.fix_missing_locations(value)) + "\n"
        factories.append(f"def _make_{name}():\n" + textwrap.indent(body, "    "))
    runtime_imports = "\n".join(
        ast.unparse(node) for node in tree.body if isinstance(node, (ast.Import, ast.ImportFrom))
    )
    runtime = (
        runtime_imports + "\n"
        "from importlib import import_module as _import_module\n"
        "from sys import version_info as _version_info\n"
        "from .._lazy_models import load_model as _load_model\n"
        "_types = _import_module('.types', __package__)\n"
        "_unions = _import_module('._unions', __package__)\n\n"
        + "\n".join(factories)
        + "\n_FACTORIES = {\n"
        + "".join(f"    {name!r}: _make_{name},\n" for name in declarations)
        + "}\n"
        + f"__all__ = {exports!r}\n\n"
        "def _resolve(name):\n"
        "    return _load_model(name, globals(), _FACTORIES, __name__)\n\n"
        "def __getattr__(name):\n"
        "    return _resolve(name)\n\n"
        "def __dir__():\n"
        "    return sorted(set(globals()) | set(__all__))\n"
    )
    output = (
        HEADER
        + "from typing import TYPE_CHECKING\n\n"
        + BEGIN
        + "if TYPE_CHECKING:\n"
        + textwrap.indent(source, "    ")
        + END
        + "else:\n"
        + textwrap.indent(runtime, "    ")
    )
    return output, exports, public_models


def emit(generated_root: Path, check: bool = False) -> None:
    types_source = canonical((generated_root / "types.py").read_text(encoding="utf-8"))
    unions_source = canonical((generated_root / "_unions.py").read_text(encoding="utf-8"))
    names = set(definitions(ast.parse(types_source)))
    types_output, type_exports, type_models = render_module(types_source, "types", names)
    unions_output, union_exports, union_models = render_module(unions_source, "_unions", names)
    generated_exports = list(dict.fromkeys(union_exports + ["types"] + type_exports))
    # The original public-model scan used dir(module), hence sorted order in each module.
    model_exports = [name for name in sorted(type_models) + sorted(union_models) if name not in MODEL_EXCLUDES]
    catalog = HEADER + (
        f"TYPE_EXPORTS = {type_exports!r}\nUNION_EXPORTS = {union_exports!r}\n"
        f"GENERATED_EXPORTS = {generated_exports!r}\nMODEL_EXPORTS = {model_exports!r}\n"
    )
    init = HEADER + """
from typing import TYPE_CHECKING
from . import types, _unions
from ._catalog import TYPE_EXPORTS as _TYPE_EXPORTS, GENERATED_EXPORTS as _GENERATED_EXPORTS

if TYPE_CHECKING:
    from ._unions import *
    from .types import *

__all__ = _GENERATED_EXPORTS

def __getattr__(name):
    if name not in __all__:
        raise AttributeError(f"module '{__name__}' has no attribute '{name}'")
    value = getattr(types if name in _TYPE_EXPORTS else _unions, name)
    globals()[name] = value
    return value

def __dir__():
    return sorted(set(globals()) | set(__all__))
"""
    for name, output in {
        "types.py": types_output,
        "_unions.py": unions_output,
        "_catalog.py": catalog,
        "__init__.py": init,
    }.items():
        path = generated_root / name
        if check:
            if path.read_text(encoding="utf-8") != output:
                raise ValueError(f"Generated model output is stale: {path}")
        else:
            path.write_text(output, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--generated-root", type=Path, required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    emit(args.generated_root, check=args.check)
